    /**
     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
     * status, a closed period, or a user not a steward.
     */
    @Transactional
    public Claim resettle(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimResettleForbiddenException(id, user);
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String old = shownDue(sheetId, person, claim);
        BigDecimal figure = dueOf(sheetId, person, claim);
        Sheet sheet = settings.get(sheetId);
        claim.setSettledDue(claim.isCorrection() ? figure
                : sheet.floored(sheet.withLateCharge(figure, !claim.isWaived(), overdueBy(sheet, person, claim), claim.getDate()), claim.getDate()));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
        rollup.recordChanges(sheetId, user, before);
        return saved;
}

/**
 * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when
 * its rounding date is before the sheet's policy date (the sheet's today when blank), half to even on or after it.
 */
export function roundingOf(claim: Claim, session: Session): Rounding {
  const mode = session.settingOn('rounding', claim.date);
  if (mode === 'half-up' || mode === 'half-even') return mode;
  const policy = session.policyDate() || session.today();
  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
}

/**
 * The due fixed when the claim was settled, else the due its person's last statement bound it to (as shown then, late
 * charge included), else the greater of the floor in force on its date and its figure (its amount times the rate of its
 * person's grade on its date, both in force on its date, or n/a with no rate) with its late charge added on top. A
 * correction has neither floor nor late charge.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
  if (claim.settledDue !== null) return claim.settledDue;
  if (bound(claim)) return claim.statedDue ?? 'n/a';
  const grade = gradeOn(grades, claim.date);
  const figure = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date, claim.rateStamp), roundingOf(claim, session));
  if (figure === 'n/a' || isCorrection(claim)) return figure;
  return floored(sumDues([figure, lateCharge(claim, figure, grades, session)]), session.settingOn('floor', claim.date));
}

/**
 * The day the claim goes overdue after, and its late charge counts from: its due-by plus the grace days of its person's
 * grade on its date in force on that date, else its due-by. The due-by shown stays as it is.
export function percentOf(amount: string, pct: string, times: number, rounding: Rounding = 'half-even'): string {
  // cents times hundredths of a percent are millionths of a unit: round them to cents.
  // A negative amount (a correction) rounds as its size does, so a half goes away from zero, or to the even cent.
  const signed = hundredths(amount) * hundredths(pct) * BigInt(times);
  const millionths = signed < 0n ? -signed : signed;
  const rest = millionths % 10000n;
  let cents = millionths / 10000n;
  if (rest > 5000n || (rest === 5000n && (rounding === 'half-up' || cents % 2n === 1n))) cents += 1n;
  return decimalOf(signed < 0n ? -cents : cents);
}

/** The due raised to the floor when below it; n/a, or no floor, leaves it as it is. */
export function floored(due: string, floor: string | null): string {
  if (due === 'n/a' || floor === null) return due;
  return hundredths(due) < hundredths(floor) ? floor : due;
}

/** The due-total held down to the cap when above it; n/a, or no cap, leaves it as it is. */
export function capped(dueTotal: string, cap: string | null): string {
  if (dueTotal === 'n/a' || cap === null) return dueTotal;
  return hundredths(dueTotal) > hundredths(cap) ? cap : dueTotal;

